import { DatabaseSync } from "node:sqlite";

// Absolute path to the SQLite database file, per project spec.
const DB_PATH = "/home/user/qwik-app/gallery.db";

export interface ImageRecord {
  id: number;
  original_name: string;
  original_path: string;
  optimized_path: string;
  width: number;
  height: number;
  uploaded_at: string;
}

let db: DatabaseSync | undefined;

/**
 * Returns a singleton SQLite database connection, creating the `images`
 * table if it doesn't already exist.
 */
export function getDb(): DatabaseSync {
  if (!db) {
    db = new DatabaseSync(DB_PATH);
    db.exec(`
      CREATE TABLE IF NOT EXISTS images (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        original_name TEXT NOT NULL,
        original_path TEXT NOT NULL,
        optimized_path TEXT NOT NULL,
        width INTEGER NOT NULL,
        height INTEGER NOT NULL,
        uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
  }
  return db;
}

export function insertImage(record: {
  original_name: string;
  original_path: string;
  optimized_path: string;
  width: number;
  height: number;
}): number {
  const database = getDb();
  const stmt = database.prepare(
    `INSERT INTO images (original_name, original_path, optimized_path, width, height)
     VALUES (?, ?, ?, ?, ?)`,
  );
  const result = stmt.run(
    record.original_name,
    record.original_path,
    record.optimized_path,
    record.width,
    record.height,
  );
  return Number(result.lastInsertRowid);
}

export function listImages(): ImageRecord[] {
  const database = getDb();
  const stmt = database.prepare(
    `SELECT id, original_name, original_path, optimized_path, width, height, uploaded_at
     FROM images
     ORDER BY uploaded_at DESC`,
  );
  return stmt.all() as unknown as ImageRecord[];
}

import { randomUUID } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

const PROJECT_ROOT = "/home/user/qwik-app";
const PUBLIC_DIR = path.join(PROJECT_ROOT, "public");

export const ORIGINAL_DIR = path.join(PUBLIC_DIR, "gallery", "original");
export const OPTIMIZED_DIR = path.join(PUBLIC_DIR, "gallery", "optimized");

export const ORIGINAL_URL_PREFIX = "/gallery/original/";
export const OPTIMIZED_URL_PREFIX = "/gallery/optimized/";

const MAX_DIMENSION = 800;

export interface ProcessedUpload {
  originalName: string;
  originalPath: string;
  optimizedPath: string;
  width: number;
  height: number;
}

/**
 * Saves the original file and a resized/optimized WebP version to disk,
 * returning the public URL paths and the optimized image dimensions.
 */
export async function processUpload(file: File): Promise<ProcessedUpload> {
  await mkdir(ORIGINAL_DIR, { recursive: true });
  await mkdir(OPTIMIZED_DIR, { recursive: true });

  const originalName = file.name || "upload";
  const ext = path.extname(originalName) || "";
  const uniqueId = randomUUID();

  const originalFileName = `${uniqueId}${ext}`;
  const optimizedFileName = `${uniqueId}.webp`;

  const arrayBuffer = await file.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);

  // Save the original file untouched.
  const originalFullPath = path.join(ORIGINAL_DIR, originalFileName);
  await writeFile(originalFullPath, buffer);

  // Resize (max dimension 800px, no upscaling) and convert to WebP.
  const optimizedFullPath = path.join(OPTIMIZED_DIR, optimizedFileName);
  const info = await sharp(buffer)
    .resize({
      width: MAX_DIMENSION,
      height: MAX_DIMENSION,
      fit: "inside",
      withoutEnlargement: true,
    })
    .webp()
    .toFile(optimizedFullPath);

  return {
    originalName,
    originalPath: `${ORIGINAL_URL_PREFIX}${originalFileName}`,
    optimizedPath: `${OPTIMIZED_URL_PREFIX}${optimizedFileName}`,
    width: info.width,
    height: info.height,
  };
}

import { component$ } from "@builder.io/qwik";
import { routeLoader$, type DocumentHead } from "@builder.io/qwik-city";
import { listImages } from "~/lib/db";

export const useGalleryImages = routeLoader$(() => {
  return listImages();
});

export default component$(() => {
  const images = useGalleryImages();

  return (
    <>
      <h1>Image Gallery</h1>

      <form
        method="post"
        action="/gallery/upload"
        encType="multipart/form-data"
      >
        <input type="file" name="image" accept="image/*" required />
        <button type="submit">Upload</button>
      </form>

      <hr />

      <div class="gallery-grid">
        {images.value.length === 0 && <p>No images uploaded yet.</p>}
        {images.value.map((image) => (
          <div class="gallery-item" key={image.id}>
            <p>{image.original_name}</p>
            <a href={image.original_path}>
              <img
                src={image.optimized_path}
                alt={image.original_name}
                width={image.width}
                height={image.height}
              />
            </a>
            <p>
              {image.width}x{image.height}
            </p>
          </div>
        ))}
      </div>
    </>
  );
});

export const head: DocumentHead = {
  title: "Image Gallery",
  meta: [
    {
      name: "description",
      content: "Upload and browse optimized images.",
    },
  ],
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { insertImage } from "~/lib/db";
import { processUpload } from "~/lib/storage";

export const onPost: RequestHandler = async (requestEvent) => {
  const formData = await requestEvent.request.formData();
  const file = formData.get("image");

  if (!(file instanceof File) || file.size === 0) {
    throw requestEvent.error(400, "No image file was provided.");
  }

  const processed = await processUpload(file);

  insertImage({
    original_name: processed.originalName,
    original_path: processed.originalPath,
    optimized_path: processed.optimizedPath,
    width: processed.width,
    height: processed.height,
  });

  throw requestEvent.redirect(303, "/gallery");
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { listImages } from "~/lib/db";

export const onGet: RequestHandler = async (requestEvent) => {
  const images = listImages().map((image) => ({
    id: image.id,
    original_name: image.original_name,
    original_path: image.original_path,
    optimized_path: image.optimized_path,
    width: image.width,
    height: image.height,
  }));

  requestEvent.json(200, images);
};

